package br.com.brasildrama.admin;
import org.junit.jupiter.api.Test;import org.springframework.http.HttpStatus;import java.time.Instant;import java.util.Optional;import java.util.UUID;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class AdminMeContractTest {
 @Test void updatesDisplayNameForCurrentActiveOperator(){var repository=mock(AdminOperatorRepository.class);var audit=mock(AdminAuditService.class);var operator=operator("Nome Antigo");var previous=operator.updatedAt;when(repository.findById(operator.id)).thenReturn(Optional.of(operator));when(repository.save(any(AdminOperator.class))).thenAnswer(i->i.getArgument(0));var api=new AdminMeApi(repository,audit);var response=api.update(()->operator.id.toString(),new AdminMeApi.UpdateProfileRequest("  Novo Nome  "));assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(operator.displayName).isEqualTo("Novo Nome");assertThat(operator.updatedAt).isAfter(previous);var profile=(AdminMeApi.AdminProfile)response.getBody();assertThat(profile.displayName()).isEqualTo("Novo Nome");verify(repository).save(operator);verify(audit).record(operator.id,"PROFILE_DISPLAY_NAME_CHANGED","ADMIN_OPERATOR",operator.id.toString(),"Nome de exibição atualizado");}
 @Test void rejectsInvalidDisplayNameWithoutPersisting(){var repository=mock(AdminOperatorRepository.class);var audit=mock(AdminAuditService.class);var operator=operator("Nome Atual");when(repository.findById(operator.id)).thenReturn(Optional.of(operator));var response=new AdminMeApi(repository,audit).update(()->operator.id.toString(),new AdminMeApi.UpdateProfileRequest(" "));assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);assertThat(operator.displayName).isEqualTo("Nome Atual");verifyNoInteractions(audit);}
 @Test void doesNotExposeInactiveOperatorAsCurrentSession(){var repository=mock(AdminOperatorRepository.class);var audit=mock(AdminAuditService.class);var operator=operator("Operador Inativo");operator.active=false;when(repository.findById(operator.id)).thenReturn(Optional.of(operator));assertThat(new AdminMeApi(repository,audit).me(()->operator.id.toString()).getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);}
 private static AdminOperator operator(String name){var o=new AdminOperator();o.id=UUID.randomUUID();o.email="operator@brasildrama.com.br";o.displayName=name;o.passwordHash="hash";o.role=AdminRole.SUPER_ADMIN;o.active=true;o.createdAt=Instant.parse("2026-08-01T10:00:00Z");o.updatedAt=Instant.parse("2026-08-20T10:00:00Z");return o;}
}
